package com.amit.jobagent.application;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;
@Entity@Table(name="application_handoff")class ApplicationHandoff{@Id UUID id;@Column(name="application_package_id",nullable=false,updatable=false)UUID packageId;@Column(name="application_package_revision_id",nullable=false,updatable=false)UUID revisionId;@Column(name="job_posting_id",nullable=false,updatable=false)UUID jobId;@Column(name="review_decision_id",nullable=false,updatable=false)UUID reviewDecisionId;@Column(name="apply_url_snapshot",nullable=false,updatable=false,length=2000)String applyUrl;@JdbcTypeCode(SqlTypes.CHAR)@Column(name="apply_url_checksum",nullable=false,updatable=false,length=64,columnDefinition="char(64)")String applyUrlChecksum;@JdbcTypeCode(SqlTypes.CHAR)@Column(name="source_job_checksum",nullable=false,updatable=false,length=64,columnDefinition="char(64)")String jobChecksum;@JdbcTypeCode(SqlTypes.CHAR)@Column(name="source_profile_checksum",nullable=false,updatable=false,length=64,columnDefinition="char(64)")String profileChecksum;@JdbcTypeCode(SqlTypes.CHAR)@Column(name="source_evaluation_checksum",nullable=false,updatable=false,length=64,columnDefinition="char(64)")String evaluationChecksum;@JdbcTypeCode(SqlTypes.CHAR)@Column(name="approved_artifact_manifest_checksum",nullable=false,updatable=false,length=64,columnDefinition="char(64)")String artifactChecksum;@JdbcTypeCode(SqlTypes.CHAR)@Column(name="creation_idempotency_hash",nullable=false,unique=true,updatable=false,length=64,columnDefinition="char(64)")String idempotencyHash;@Enumerated(EnumType.STRING)@Column(nullable=false,length=40)ApplicationHandoffStatus status;@Column(name="created_by",nullable=false,updatable=false,length=150)String createdBy;@Column(name="created_at",nullable=false,updatable=false)Instant createdAt;@Column(name="updated_at",nullable=false)Instant updatedAt;@Column(name="launched_at")Instant launchedAt;@Column(name="submission_reported_at")Instant submissionReportedAt;@Version@Column(name="record_version",nullable=false)long recordVersion;protected ApplicationHandoff(){}ApplicationHandoff(UUID pkg,UUID revision,UUID job,UUID decision,String url,String urlHash,String jobHash,String profileHash,String evalHash,String artifactHash,String key,String actor){id=UUID.randomUUID();packageId=pkg;revisionId=revision;jobId=job;reviewDecisionId=decision;applyUrl=url;applyUrlChecksum=urlHash;jobChecksum=jobHash;profileChecksum=profileHash;evaluationChecksum=evalHash;artifactChecksum=artifactHash;idempotencyHash=key;createdBy=actor;status=ApplicationHandoffStatus.READY_FOR_MANUAL_SUBMISSION;createdAt=Instant.now();updatedAt=createdAt;}void transition(ApplicationHandoffStatus next){status=next;updatedAt=Instant.now();if(next==ApplicationHandoffStatus.OPENED_EXTERNALLY&&launchedAt==null)launchedAt=updatedAt;if(next==ApplicationHandoffStatus.SUBMITTED_REPORTED_BY_USER)submissionReportedAt=updatedAt;}}
